export interface ModifierRecorderByScope {
  readonly army: ArmyModifierRecorder;
  readonly astral_rift: AstralRiftModifierRecorder;
  readonly colony: ColonyModifierRecorder;
  readonly country: CountryModifierRecorder;
  readonly deposit: DepositModifierRecorder;
  readonly design: DesignModifierRecorder;
  readonly federation: FederationModifierRecorder;
  readonly fleet: FleetModifierRecorder;
  readonly leader: LeaderModifierRecorder;
  readonly megastructure: MegastructureModifierRecorder;
  readonly planet: PlanetModifierRecorder;
  readonly pop_faction: PopFactionModifierRecorder;
  readonly pop_group: PopGroupModifierRecorder;
  readonly sector: SectorModifierRecorder;
  readonly ship: ShipModifierRecorder;
  readonly species: SpeciesModifierRecorder;
  readonly spy_network: SpyNetworkModifierRecorder;
  readonly starbase: StarbaseModifierRecorder;
  readonly system: SystemModifierRecorder;
}

/**
 * The recorder for scopes the modifier tables do not cover: no path data,
 * so only the by-name escape hatches.
 */
export interface UnscopedModifierRecorder {
  /** Sets a modifier by its flat name. */
  raw(name: string, value: number): void;
  /** Sets a modifier by an arbitrary, unchecked name. */
  unchecked(name: string, value: number): void;
}

/**
 * Records any known modifier, for positions the rules leave unscoped.
 * The paths of every scope at once — `m.country.unity.produces.mult(0.15)`
 * and `m.planet.jobs.alloys.produces.mult(0.1)` both resolve here.
 */
export interface AnyScopeModifierRecorder extends ModifierPath3456 {
  /** Sets a modifier by its flat name, checked against every known name. */
  raw(name: keyof AnyScopeModifierBlock & string, value: number): void;
  /** Sets a modifier by an arbitrary, unchecked name. */
  unchecked(name: string, value: number): void;
}

/**
 * The modifier recorder for scope `S`.
 * An unconstrained `S` is checked first and without distributing: it means
 * the rules pin no scope, so every path is legal. Distributing it instead
 * would produce a union of every per-scope recorder with no member in
 * common — not even `raw`, whose name parameter would intersect to `never`.
 */
export type ScopedModifierRecorder<S extends ScopeName> = [ScopeName] extends [S]
  ? AnyScopeModifierRecorder
  : S extends keyof ModifierRecorderByScope
    ? ModifierRecorderByScope[S]
    : UnscopedModifierRecorder;
